    if self.cwd_real.starts_with('/') {
        self.cwd_kind = 1;
    } else if self.cwd_real.chars().nth(1) == Some(':') {
        self.cwd_kind = 2;
    } else if self.cwd_real.starts_with('~') {
        self.cwd_kind = 3;
    } else if self.cwd_real.is_empty() {
        self.cwd_kind = 0;
    } else {
        self.cwd_kind = 4;
    }
    let _ = self.classify_lookup_cwd(&self.cwd_real.clone());
    let _ = self.normalize_host_path_0(&self.cwd_real.clone());
