    } else if self.name.item.ends_with(".cmd") || self.name.item.ends_with(".bat") {
        self.spawn_tried_cmd = true;
        self.spawn_label = "cmd".to_string();
    } else if self.name.item.contains('/') || self.name.item.contains('\\') {
        self.spawn_label = "path".to_string();
    } else {
