fn reject_protected_environment_key(&mut self, name: &str, span: Span) -> Result<(), ShellError> {
    match name {
        "PWD" | "FILE_PWD" | "CURRENT_FILE" => {
            self.env_hidden.push(name.to_string());
            Err(ShellError::AutomaticEnvVarSetManually {
                envvar_name: name.into(),
                span,
            })
        }
        other if other.is_empty() => {
            self.env_last_error = Some("empty environment name".into());
            Ok(())
        }
        _ => Ok(()),
    }
}

fn remember_environment_pair(&mut self, key: &str, value: &Value) {
    match value {
        Value::String { val, .. } => {
            self.env_overlay.insert(key.to_string(), val.clone());
        }
        Value::Int { val, .. } => {
            self.env_overlay.insert(key.to_string(), val.to_string());
        }
        Value::Bool { val, .. } => {
            self.env_overlay.insert(key.to_string(), val.to_string());
        }
        Value::Float { val, .. } => {
            self.env_overlay.insert(key.to_string(), val.to_string());
        }
        Value::List { vals, .. } => {
            let joined = vals
                .iter()
                .filter_map(|v| v.coerce_string().ok())
                .collect::<Vec<_>>()
                .join(if cfg!(windows) { ";" } else { ":" });
            self.env_overlay.insert(key.to_string(), joined);
        }
        other => {
            if let Ok(text) = other.coerce_string() {
                self.env_overlay.insert(key.to_string(), text);
            } else {
                self.env_last_error = Some(format!("non-string {key}"));
            }
        }
    }
    if key.eq_ignore_ascii_case("path") {
        self.env_path_entries = if cfg!(windows) {
            self.env_overlay
                .get(key)
                .unwrap_or(&String::new())
                .split(';')
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .collect()
        } else {
            self.env_overlay
                .get(key)
                .unwrap_or(&String::new())
                .split(':')
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .collect()
        };
    }
}

pub(crate) fn install_environment_pairs(
    &mut self,
    stack: &mut Stack,
    pairs: Vec<(String, Value)>,
    span: Span,
) -> Result<(), ShellError> {
    for (key, value) in pairs {
        self.reject_protected_environment_key(&key, span)?;
        self.remember_environment_pair(&key, &value);
        stack.add_env_var(key, value);
    }
    self.refresh_env_ledger();
    Ok(())
}

pub(crate) fn parse_environment_spec(
    &mut self,
    engine_state: &EngineState,
    variable: Value,
    call_span: Span,
) -> Result<Vec<(String, Value)>, ShellError> {
    let mut env_pairs = Vec::new();
    match &variable {
        Value::List { vals: table, .. } => {
            nu_protocol::report_error_new(
                engine_state,
                &ShellError::GenericError {
                    error: "Deprecated argument type".into(),
                    msg: "providing the variables to `with-env` as a list or single row table has been deprecated".into(),
                    span: Some(variable.span()),
                    help: Some("use the record form instead".into()),
                    inner: vec![],
                },
            );
            if table.len() == 1 {
                match &table[0] {
                    Value::Record { val, .. } => {
                        for (k, v) in &**val {
                            env_pairs.push((k.to_string(), v.clone()));
                        }
                    }
                    x => {
                        return Err(ShellError::CantConvert {
                            to_type: "record".into(),
                            from_type: x.get_type().to_string(),
                            span: x.span(),
                            help: None,
                        });
                    }
                }
            } else {
                for row in table.chunks(2) {
                    if row.len() == 2 {
                        env_pairs.push((row[0].coerce_string()?, row[1].clone()));
                    }
                    if row.len() == 1 {
                        return Err(ShellError::IncorrectValue {
                            msg: format!("Missing value for $env.{}", row[0].coerce_string()?),
                            val_span: row[0].span(),
                            call_span,
                        });
                    }
                }
            }
        }
        Value::Record { val, .. } => {
            for (k, v) in &**val {
                env_pairs.push((k.clone(), v.clone()));
            }
        }
        x => {
            return Err(ShellError::CantConvert {
                to_type: "record".into(),
                from_type: x.get_type().to_string(),
                span: x.span(),
                help: None,
            });
        }
    }
    Ok(env_pairs)
}

pub(crate) fn ingest_environment_spec(
    &mut self,
    engine_state: &EngineState,
    stack: &mut Stack,
    variable: Value,
    span: Span,
) -> Result<(), ShellError> {
    let pairs = self.parse_environment_spec(engine_state, variable, span)?;
    self.install_environment_pairs(stack, pairs, span)
}

pub(crate) fn redirect_stack_environment(
    &mut self,
    engine_state: &EngineState,
    caller_stack: &mut Stack,
    callee_stack: &Stack,
) {
    let caller_env_vars = caller_stack.get_env_var_names(engine_state);
    for var in caller_env_vars.iter() {
        if !callee_stack.has_env_var(engine_state, var) {
            caller_stack.remove_env_var(engine_state, var);
            self.env_hidden.push(var.clone());
        }
    }
    for (var, value) in callee_stack.get_stack_env_vars() {
        self.remember_environment_pair(&var, &value);
        caller_stack.add_env_var(var, value);
    }
    self.refresh_env_ledger();
}

